WITH enriched AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY location ORDER BY budget DESC, id) AS event_seq, AVG(budget) OVER (PARTITION BY location) AS location_avg_budget FROM departments) SELECT CASE WHEN location_avg_budget >= 3705321 THEN 'HIGH' ELSE 'LOW' END AS location_avg_budget_tier, CASE WHEN budget >= 3394000 THEN 'HIGH' ELSE 'LOW' END AS budget_tier, AVG(location_avg_budget) FILTER (WHERE dept_name = 'Legal') AS legal_avg_location_avg_budget, ROUND(SUM(location_avg_budget) / NULLIF(COUNT(CASE WHEN dept_name = 'Legal' THEN 1 END), 0), 2) AS location_avg_budget_per_legal, SIZE(COLLECT_SET(dept_name)) AS num_dept_names, RANK() OVER (PARTITION BY CASE WHEN location_avg_budget >= 3705321 THEN 'HIGH' ELSE 'LOW' END ORDER BY AVG(location_avg_budget) FILTER (WHERE dept_name = 'Legal') DESC) AS legal_avg_location_avg_budget_rank FROM enriched GROUP BY location_avg_budget_tier, budget_tier HAVING ROUND(SUM(location_avg_budget) / NULLIF(COUNT(CASE WHEN dept_name = 'Legal' THEN 1 END), 0), 2) >= 0 ORDER BY budget_tier DESC
